import { useEffect, useMemo, useRef } from 'react';

import type { KpiGroup } from 'domain/Kpi';
import { useBffData, useMediaQuery } from 'hooks';
import { FilterForm } from 'models';
import { WaterfallData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import { COMMERCIAL_RESULTS_WATERFALL_BFF_ID } from '../../constants';
import { UseWaterfallData } from '../../types';
import { getCommercialResultsSubFilters } from '../../utils/getCommercialResultsSubFilters';

interface UseWaterfallDataProps {
  formatMessage: (descriptor: { id: string }) => string;
  activeSubFilters: Record<string, unknown>;
  applied: FilterForm;
  kpiGroup: string;
}

function extractWaterfallData(
  data: Record<string, unknown> | null | undefined,
  waterfallVariant: 'large' | 'small',
): WaterfallData | null {
  const raw = data?.[waterfallVariant];
  if (data?.empty || !raw || typeof raw !== 'object') {
    return { empty: true, labels: [] };
  }

  return raw as WaterfallData;
}

export const useWaterfallData = ({
  formatMessage,
  activeSubFilters,
  applied,
  kpiGroup,
}: UseWaterfallDataProps): UseWaterfallData => {
  const isLargeScreen = useMediaQuery('(min-width: 1440px)');
  const waterfallVariant = useMemo(() => {
    return isLargeScreen ? 'large' : 'small';
  }, [isLargeScreen]);
  const previousWaterfallFilterRef = useRef<string | undefined>(undefined);
  const previousPeriodFilterRef = useRef<string | undefined>(undefined);
  const isSkuView = activeSubFilters?.waterfall_filter === 'sku';
  const periodChanged =
    previousPeriodFilterRef.current !== (applied.periods as string | undefined);

  const subFilters = useMemo(
    () => ({
      ...getCommercialResultsSubFilters(applied),
      sku:
        isSkuView && periodChanged
          ? 'All'
          : getCommercialResultsSubFilters(applied).sku,
      waterfall_filter: activeSubFilters?.waterfall_filter,
    }),
    [applied, activeSubFilters, isSkuView, periodChanged],
  );
  const currentWaterfallFilter = subFilters?.waterfall_filter as
    | string
    | undefined;

  useEffect(() => {
    previousWaterfallFilterRef.current = currentWaterfallFilter;
    previousPeriodFilterRef.current = applied.periods as string;
  }, [currentWaterfallFilter, applied.periods]);

  const shouldSkipRequest = useMemo(() => {
    const hasWaterfallFilterChanged =
      previousWaterfallFilterRef.current !== currentWaterfallFilter;
    const isSkuLevel = currentWaterfallFilter === 'sku';
    const hasPeriodFilterChanged =
      previousPeriodFilterRef.current !== applied.periods;

    if (hasWaterfallFilterChanged || !isSkuLevel || hasPeriodFilterChanged) {
      return false;
    }
    return true;
  }, [currentWaterfallFilter, applied]);

  const waterfallBffData = useBffData({
    id: COMMERCIAL_RESULTS_WATERFALL_BFF_ID,
    kpiGroup: kpiGroup as KpiGroup,
    subFilters,
    skipMainFilters: false,
    skipRequest: shouldSkipRequest,
  });

  const waterfallChartData = useMemo(
    () =>
      extractWaterfallData(
        waterfallBffData?.data?.contribution as Record<string, unknown>,
        waterfallVariant,
      ),
    [waterfallBffData?.data, waterfallVariant],
  );

  return {
    waterfallData: waterfallChartData,
    title: formatMessage({
      id: 'ValueCreation.CommercialResults.performance.waterfallTitle',
    }),
    loading: waterfallBffData?.loading,
    error: waterfallBffData?.error,
    waterfallVariant,
  };
};
